using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using AICad.Geometry;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Newtonsoft.Json.Linq;
using JsonUtil=AICad.Contracts.Json;
namespace AICad.Bridge;
internal static partial class Reader {
 internal static JObject Geometry(Entity e){Point2 P(Point3d p){if(Math.Abs(p.Z)>1e-6)throw new CadException("UNSUPPORTED_GEOMETRY","3D entity is not flattened.");return new(p.X,p.Y);}if(e is Line l)return JObject.FromObject(new{kind="line",points=new[]{P(l.StartPoint),P(l.EndPoint)},length=l.Length});if(e is Polyline pl){if((pl.Normal-Vector3d.ZAxis).Length>1e-6||Math.Abs(pl.Elevation)>1e-6)return new(){["status"]="UNSUPPORTED_3D"};var points=new List<Point2>();for(int i=0;i<pl.NumberOfVertices;i++){if(Math.Abs(pl.GetBulgeAt(i))>1e-9)return new(){["status"]="UNSUPPORTED_CURVED_POLYLINE"};points.Add(P(pl.GetPoint3dAt(i)));}return JObject.FromObject(new{kind="polyline",points,closed=pl.Closed,length=pl.Length});}if(e is Circle circle)return JObject.FromObject(new{kind="circle",center=P(circle.Center),radius=circle.Radius});if(e is Arc arc)return JObject.FromObject(new{kind="arc",center=P(arc.Center),radius=arc.Radius,start=arc.StartAngle,end=arc.EndAngle});if(e is DBText text)return JObject.FromObject(new{kind="text",position=P(text.Position),text=text.TextString,height=text.Height});if(e is Dimension dim)return JObject.FromObject(new{kind="dimension",measurement=dim.Measurement});if(e is BlockReference b)return JObject.FromObject(new{kind="block",position=P(b.Position),rotation=b.Rotation});return new(){["status"]="METADATA_ONLY"};}
 internal static JObject Read(Document d,JObject args){int offset=args.Value<int?>("offset")??0,limit=args.Value<int?>("limit")??100;if(offset<0||limit<1||limit>200)throw new CadException("INVALID_PAGE","limit must be 1–200.");HashSet<string>? handles=args["handles"] is JArray selected?new HashSet<string>(selected.Values<string>().Select(x=>x!),StringComparer.OrdinalIgnoreCase):null;if(handles!=null&&(handles.Count<1||handles.Count>200||handles.Any(h=>h.Length<1||h.Length>16||h.Any(c=>!Uri.IsHexDigit(c)))))throw new CadException("INVALID_HANDLE","Bounded hexadecimal handles required.");var scope=args["scope"]?.ToObject<List<Point2>>();if(scope!=null)Validation.Scope(scope);using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);var rows=new JArray();int matched=0,scanned=0;bool more=false;foreach(ObjectId id in ms){if(++scanned>100000)throw new CadException("SCAN_LIMIT","Limit 100,000 entities.");if(id.IsErased||handles!=null&&!handles.Contains(id.Handle.ToString()))continue;var e=tx.GetObject(id,OpenMode.ForRead) as Entity;if(e==null)continue;JObject? bounds=null;string relation="unfiltered";try{var ex=e.GeometricExtents;var box=Validation.Box(ex.MinPoint.X,ex.MinPoint.Y,ex.MaxPoint.X,ex.MaxPoint.Y).ToList();bounds=new(){["minX"]=ex.MinPoint.X,["minY"]=ex.MinPoint.Y,["maxX"]=ex.MaxPoint.X,["maxY"]=ex.MaxPoint.Y};if(scope!=null){bool inside=box.All(p=>Validation.Contains(scope,p));if(!inside&&!Overlap(scope,box))continue;relation=inside?"inside":"crosses";}}catch(Autodesk.AutoCAD.Runtime.Exception){if(scope!=null)continue;}if(matched++<offset)continue;if(rows.Count==limit){more=true;break;}var row=new JObject{["handle"]=e.Handle.ToString(),["type"]=e.GetType().Name,["layer"]=e.Layer,["scopeRelation"]=relation,["bounds"]=bounds};try{row["geometry"]=Geometry(e);}catch(CadException err){row["geometry"]=new JObject{["status"]=err.Code};}rows.Add(row);}return new(){["entities"]=rows,["nextOffset"]=more?new JValue(offset+limit):JValue.CreateNull()};}
 internal static JObject Inspect(Document d,PlanFiles plans,string planId){var record=plans.Read(JsonUtil.Id(planId));using var tx=d.Database.TransactionManager.StartOpenCloseTransaction();var nod=(DBDictionary)tx.GetObject(d.Database.NamedObjectsDictionaryId,OpenMode.ForRead);string key="AICAD_"+planId;if(!nod.Contains(key))return new(){["status"]="MISSING_RECEIPT",["message"]="Execution may be undone, unsaved or not committed. No automatic retry."};var receipt=(Xrecord)tx.GetObject(nod.GetAt(key),OpenMode.ForRead);var values=receipt.Data.AsArray();if(values.Length<3||values[0].Value.ToString()!=record.Hash||values[1].Value.ToString()!=record.ExecutionId||values[2].Value.ToString()!=JsonUtil.Hash(record.EntityHandles))throw new CadException("RECEIPT_MISMATCH","Receipt differs from execution journal.");var errors=new JArray();for(int i=0;i<record.EntityHandles.Count;i++)try{var id=d.Database.GetObjectId(false,new Handle(Convert.ToInt64(record.EntityHandles[i],16)),0);var e=(Entity)tx.GetObject(id,OpenMode.ForRead);if(e.IsErased||e.Layer!=record.Plan.Operations[i].Layer)throw new CadException("QA_MISMATCH","Entity erased or layer changed.");EntityFactory.DemandBounds(e,record.Plan);}catch(System.Exception err){errors.Add(record.EntityHandles[i]+": "+err.Message);}return new(){["status"]=errors.Count==0?"PRESENT":"CHANGED",["handlesConfirmed"]=record.EntityHandles.Count-errors.Count,["errors"]=errors};}
}
